// Promo QC data (admin/videos). The JSON files under src/data/video-qc
// are generated by ~/workspace/gtm/bigbrainshelf/build_video_qc_data.py
// from the promo projects, the attempts ledger, and the pixel safe-zone
// checker; media (video + frames) lives in the BOOKS R2 bucket under
// video-qc/<slug>/ and is served through /api/admin/media.

export interface QcElement {
  id: string;
  name: string;
  text: string;
  box: [number, number, number, number] | null;
  entry_s: number | null;
  entry_in_scene_s: number | null;
  trigger_word: string | null;
  trigger_at_s: number | null;
  zone: { inside: boolean; breach_px: number } | null;
}

export interface QcScene {
  id: string;
  name: string;
  start_s: number;
  end_s: number;
  duration_s: number;
  line: string;
  frame_key: string;
  frame_t_s: number;
  measured_fg_violations: number | null;
  elements: QcElement[];
}

export interface QcVideo {
  slug: string;
  title: string;
  product: string;
  style: string;
  attempt_id: string;
  duration_s: number | null;
  lufs: number | null;
  true_peak_db: number | null;
  transcript: { ratio: number | null; state: string } | null;
  verdict: string | null;
  defect_tags: string[];
  safezone_fg_violations: number | null;
  safezone_elements_measured: number | null;
  video_key: string;
  poster_key: string | null;
  scenes: QcScene[];
}

const modules = import.meta.glob("../data/video-qc/*.json", { eager: true }) as Record<
  string,
  { default: any }
>;

const videos: QcVideo[] = Object.entries(modules)
  .filter(([path]) => !path.endsWith("/index.json"))
  .map(([, mod]) => mod.default as QcVideo)
  .sort((a, b) => a.slug.localeCompare(b.slug));

export function listQcVideos(): QcVideo[] {
  return videos;
}

export function getQcVideo(slug: string): QcVideo | undefined {
  return videos.find((v) => v.slug === slug);
}

export function getQcScene(video: QcVideo, sceneId: string): QcScene | undefined {
  return video.scenes.find((s) => s.id === sceneId);
}

export function mediaUrl(key: string): string {
  return "/api/admin/media?key=" + encodeURIComponent(key);
}

export function fmtTime(s: number | null | undefined): string {
  if (s == null || isNaN(Number(s))) return "";
  const v = Number(s);
  const m = Math.floor(v / 60);
  const sec = v - m * 60;
  return m > 0 ? `${m}:${sec.toFixed(1).padStart(4, "0")}` : `${sec.toFixed(1)}s`;
}
